local KTool = CS.Engine.Lib.KTool
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

---@class TipsService
local TipsService = Class("TipsService")

function TipsService.new(luaDialog)
    local instance = TipsService.New()
    instance.luaDialog = luaDialog

    for k, v in pairs(luaDialog) do
        instance[k] = v
    end
    SetButtonAction(instance.BtnTips, Bind(instance, instance.OnClick))
    return instance
end

function TipsService:UpdateInfo()
    local isShow = checkNumber(self.targetFishId) > 0
    if not isShow then return end
    CfUtils.SetActive(self.RemindTips, isShow)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.targetFishId)
    local fishName = vo.name
    --CfUtils.FillText(self.TextDesc1, localize("本次目标:<color=#ff46bd>_name_</color>", {_name_ = vo.name}))
    vo = FishingUtils.GetFishingSpeciesVo(self.targetFishId)

    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.unlock)
    if (not self._showOnlyFish) and foodVo then
        CfUtils.FillText(self.TextDesc1, localize("本次目标:<color=#ff46bd>_name_食谱</color>", {_name_ = checkString(foodVo.name)}))
    else
        CfUtils.FillText(self.TextDesc1, localize("本次目标:<color=#ff46bd>_name_</color>", {_name_ = fishName}))
    end

    local recommendBaitVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.recommendBait)
    if recommendBaitVo then
        CfUtils.FillText(self.TextDesc2, localize("推荐使用:<color=#ff46bd>_name_</color>", {_name_ = recommendBaitVo.name}))
    end
end

function TipsService:ShowMe()
    self:UpdateInfo()
end

function TipsService:HideMe()
    self.luaDialog.CoRemindTipHide = cs_coroutine.start(function()
        CfUtils.PlayAnimation(self.RemindTips, "FishPoolGoFishingDialog_RemindTips_Back")
        cs_coroutine.yield_return(WaitForSeconds(0.33))
        CfUtils.SetActive(self.RemindTips, false)
        self.luaDialog.CoRemindTipHide = nil
    end)
end

function TipsService:OnClick()
    local tipsDisPlay = self.RemindTips.transform:Find("TipsDisplay")
    local isActive = CfUtils.IsActive(tipsDisPlay)
    CfUtils.SetActive(tipsDisPlay, not isActive)
end

return TipsService